import{_ as l,C as a,o as s,c as g,E as o,a3 as r}from"./chunks/framework.Q4yG9rk_.js";const q=JSON.parse('{"title":"泰卦","description":"第十一卦·地天泰——天地交，万物通","frontmatter":{"title":"泰卦","description":"第十一卦·地天泰——天地交，万物通","category":"hexagram","aliases":["泰","地天泰"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/11-ditiantai.md","filePath":"yijing/hexagrams/11-ditiantai.md","lastUpdated":1789987057000}'),d={name:"yijing/hexagrams/11-ditiantai.md"};function p(h,t,u,c,x,b){const i=a("DaoHexagramViewer"),n=a("DaoHexagramYaoCards"),e=a("DaoKeywordCards");return s(),g("div",null,[o(i,{name:"泰",fullName:"地天泰",upper:"☷",lower:"☰",guaCi:"泰，小往大来，吉亨。",pinyin:["tài"],element:"土",direction:"西南",guaSlug:"11ditiantai",lines:[{position:"初九",type:"yang",text:"拔茅茹，以其汇，征吉。",xiang:"拔茅征吉，志在外也。"},{position:"九二",type:"yang",text:"包荒，用冯河，不遐遗，朋亡，得尚于中行。",xiang:"包荒得尚于中行，以光大也。"},{position:"九三",type:"yang",text:"无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。",xiang:"无往不复，天地际也。"},{position:"六四",type:"yin",text:"翩翩，不富以其邻，不戒以孚。",xiang:"翩翩不富，皆失实也。不戒以孚，中心愿也。"},{position:"六五",type:"yin",text:"帝乙归妹，以祉元吉。",xiang:"以祉元吉，中以行愿也。"},{position:"上六",type:"yin",text:"城复于隍，勿用师，自邑告命，贞吝。",xiang:"城复于隍，其命乱也。"}]}),t[0]||(t[0]=r('<h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>泰，小往大来，吉亨。则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人。君子道长，小人道消也。</p><h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>天地交，泰。后以财成天地之道，辅相天地之宜，以左右民。</p><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',5)),o(n,{element:"土",guaSlug:"11ditiantai",items:[{position:"初九",text:"拔茅茹，以其汇，征吉。",xiang:"拔茅征吉，志在外也。"},{position:"九二",text:"包荒，用冯河，不遐遗，朋亡，得尚于中行。",xiang:"包荒得尚于中行，以光大也。"},{position:"九三",text:"无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。",xiang:"无往不复，天地际也。"},{position:"六四",text:"翩翩，不富以其邻，不戒以孚。",xiang:"翩翩不富，皆失实也。不戒以孚，中心愿也。"},{position:"六五",text:"帝乙归妹，以祉元吉。",xiang:"以祉元吉，中以行愿也。"},{position:"上六",text:"城复于隍，勿用师，自邑告命，贞吝。",xiang:"城复于隍，其命乱也。"}]}),t[1]||(t[1]=r('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初九-·-拔茅茹-以其汇-征吉" tabindex="-1">初九 · 拔茅茹，以其汇，征吉 <a class="header-anchor" href="#初九-·-拔茅茹-以其汇-征吉" aria-label="Permalink to &quot;初九 · 拔茅茹，以其汇，征吉&quot;">​</a></h3><p><strong>核心：顺应</strong></p><p>茅草连根而生，拔起一根，牵动一片根系。顺应那股向上的阳气，动起来即通达。</p><p>这是泰卦开局的姿态——不是孤立地前进，而是带着同类一起，自然而然地动。</p><h3 id="九二-·-包荒-用冯河-不遐遗-朋亡-得尚于中行" tabindex="-1">九二 · 包荒，用冯河，不遐遗，朋亡，得尚于中行 <a class="header-anchor" href="#九二-·-包荒-用冯河-不遐遗-朋亡-得尚于中行" aria-label="Permalink to &quot;九二 · 包荒，用冯河，不遐遗，朋亡，得尚于中行&quot;">​</a></h3><p><strong>核心：自然呈现</strong></p><p>气通之后自然展现的四种品质：</p><ul><li><strong>包荒</strong>——包容（连荒芜、污秽也能容纳）</li><li><strong>用冯河</strong>——勇气（不假外力，徒步涉险的莽勇与自信）</li><li><strong>不遐遗</strong>——广阔视野（连偏远难及之处也不遗漏）</li><li><strong>朋亡</strong>——超越私党（不结党营私）</li></ul><p>这不是一份修行清单，而是<strong>气通了之后，自然呈现的泰然状态</strong>。落脚点在「得尚于中行」——一切都合于中道而行。</p><h3 id="九三-·-无平不陂-无往不复-艰贞无咎-勿恤其孚-于食有福" tabindex="-1">九三 · 无平不陂，无往不复；艰贞无咎，勿恤其孚，于食有福 <a class="header-anchor" href="#九三-·-无平不陂-无往不复-艰贞无咎-勿恤其孚-于食有福" aria-label="Permalink to &quot;九三 · 无平不陂，无往不复；艰贞无咎，勿恤其孚，于食有福&quot;">​</a></h3><p><strong>核心：清醒唤醒</strong></p><ul><li><strong>无平不陂，无往不复</strong>——天道规律：没有永远的平坦，没有永远的前行不返。在泰的顶端保持清醒，警惕惯性与麻木。</li><li><strong>艰贞无咎</strong>——「艰」既是程度副词（费力地守正），也是过程描述（持续不断、不可心血来潮），需要日日重新用力，方能无咎。</li><li><strong>勿恤其孚</strong>——不必过度忧虑外界的认可与回应是否减少，守住内在的诚信本心，根本自然有福（于食有福）。</li></ul><blockquote><p>九三是「开始之后如何不半途而弃」的处境，比初九的「迈出一步」更难，也更真实。</p></blockquote><h3 id="六四-·-翩翩不富-以其邻-不戒以孚" tabindex="-1">六四 · 翩翩不富，以其邻，不戒以孚 <a class="header-anchor" href="#六四-·-翩翩不富-以其邻-不戒以孚" aria-label="Permalink to &quot;六四 · 翩翩不富，以其邻，不戒以孚&quot;">​</a></h3><p><strong>核心：轻盈往下</strong></p><p>六四是外卦（坤）第一爻，方向由内向外、由上向下。</p><ul><li><strong>翩翩</strong>——不是飞扬，是轻盈地放下，没有负担地往下走。</li><li><strong>不富</strong>——不自满，不抱着已有的东西不放。</li><li><strong>以其邻</strong>——带着周围的人一起，自然带动。</li><li><strong>不戒以孚</strong>——不需要刻意告诫、宣传，凭真诚本身就够了。</li></ul><blockquote><p>真正的富，不止财富之象，更是精神、性命、神等多个层面的充实。而「富而不自知」——不自觉地带动周围人跟随——恰恰是最健康的富的状态；一旦意识到「我很富」，往往开始变质为经营与表演。</p></blockquote><h3 id="六五-·-帝乙归妹-以祉元吉" tabindex="-1">六五 · 帝乙归妹，以祉元吉 <a class="header-anchor" href="#六五-·-帝乙归妹-以祉元吉" aria-label="Permalink to &quot;六五 · 帝乙归妹，以祉元吉&quot;">​</a></h3><p><strong>核心：放低与联结</strong></p><p>典出商王帝乙将女儿下嫁诸侯——天子之女，却要以妇礼事夫家，是一种<strong>真正的放低</strong>，不是姿态上的谦逊。</p><p>六五居君位却是阴爻，以柔顺、联结、往下走的方式统治，而非用权威压制。这与六四的「翩翩不富」一脉相承——不是往上拔高自己，而是往下流动，维持上下之气的贯通。</p><h4 id="君柔臣刚的结构-六五-vs-九二" tabindex="-1">君柔臣刚的结构（六五 vs 九二） <a class="header-anchor" href="#君柔臣刚的结构-六五-vs-九二" aria-label="Permalink to &quot;君柔臣刚的结构（六五 vs 九二）&quot;">​</a></h4><blockquote><p><strong>臣刚而能谏，君婉而能施。</strong></p></blockquote><ul><li>九二之刚：根基是「中」——不偏不倚，气通后自然呈现的担当，不是为刚而刚。</li><li>六五之柔：根基是「孚」——真诚的放低，不是软弱或表演式的谦逊。</li></ul><p>这个结构只在「泰」的处境下健康：气本已流动，刚柔各得其位、各尽其性，才能真正交汇。</p><h3 id="上六-·-城复于隍-勿用师-自邑告命-贞吝" tabindex="-1">上六 · 城复于隍，勿用师，自邑告命，贞吝 <a class="header-anchor" href="#上六-·-城复于隍-勿用师-自邑告命-贞吝" aria-label="Permalink to &quot;上六 · 城复于隍，勿用师，自邑告命，贞吝&quot;">​</a></h3><p><strong>核心：回归与守本</strong></p><ul><li><strong>城复于隍</strong>——筑城之土本取自护城河，城塌了，土归原处。泰极而否，不是被攻破，而是自然的回归。</li><li><strong>勿用师</strong>——不可强行用力挽回，否则加速崩塌。</li><li><strong>自邑告命</strong>——退回自己能掌握的范围，守好根本，而非妄图号令天下。</li><li><strong>贞吝</strong>——即便守正，仍有遗憾与艰难；这份遗憾是天道运行的必然，不是过失。</li></ul><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',31)),o(e,{title:"字词释义",items:[{term:"孚",pinyin:["fú"],meaning:"诚信、信实"},{term:"咎",pinyin:["jiù"],meaning:"灾祸、罪过"},{term:"吝",pinyin:["lìn"],meaning:"憾惜、艰难"}]}),t[2]||(t[2]=r('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p><strong>地天泰</strong>：乾下坤上，天在下，地在上。</p><p>表面看似「错位」，实则暗藏泰的核心机密——</p><blockquote><p>天气本性向上升，地气本性向下沉。 天在下，其气自然往上走；地在上，其气自然往下走。 上下相交，气脉贯通，此为「泰」。</p></blockquote><p><strong>否卦</strong>则相反：天在上（天气本就往上走，出不去），地在下（地气本就往下沉，进不来），上下不交，故为「否」。</p><p>泰不是「躺着就能维持的舒适区」，而是一种<strong>气在流动、君子道长</strong>的动态平衡状态。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p><strong>彖传</strong>释卦辞之理：天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人，君子道长，小人道消也。</p><p><strong>象传</strong>：天地交，泰；后以财成天地之道，辅相万物之宜，以左右民。君王体察「天地交」之象，以此裁成天地之道，辅助万物各得其宜，从而治理百姓。</p><p>泰的核心不只是「通」，更是「交」——上下相交、内外相应。真正的通达来自气的流动与交合，而非静止的平稳。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><p>功夫不在于雕刻行为，而在于「通气」——内部阳气流动，外部自然通达，君子之德自然长成。</p><ul><li><strong>初九</strong>：动起来本身就是答案，带着同类一起动</li><li><strong>九二</strong>：气通了，包容、勇气、视野、无私会自然呈现，不必刻意修</li><li><strong>九三</strong>：在顺境顶端保持清醒，日日重新守正</li><li><strong>六四</strong>：轻盈地往下走，不抱着已有的东西不放</li><li><strong>六五</strong>：真正的放低，不是姿态上的谦逊，而是往下流动</li><li><strong>上六</strong>：泰极而否是自然回归，守好根本，不强行挽回</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>泰卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞关键词</th><th>核心逻辑</th></tr></thead><tbody><tr><td>初九</td><td>拔茅茹，征吉</td><td>顺应，动起来</td></tr><tr><td>九二</td><td>包荒，得尚于中行</td><td>自然呈现，气通</td></tr><tr><td>九三</td><td>无平不陂，艰贞无咎</td><td>清醒，居安思危</td></tr><tr><td>六四</td><td>翩翩不富，不戒以孚</td><td>轻盈，自然带动</td></tr><tr><td>六五</td><td>帝乙归妹，元吉</td><td>放低，真诚联结</td></tr><tr><td>上六</td><td>城复于隍，贞吝</td><td>回归，守住根本</td></tr></tbody></table><p>这六爻走的是一条完整的弧线：<strong>从泰的开启，到泰的极致，到泰的回归。</strong></p><p>核心洞见：</p><ol><li><strong>泰的本质是通气</strong>——不是舒适区，而是阳气流动带来的动态平衡</li><li><strong>九二的四种品质是果不是因</strong>——气通之后自然呈现，不是修行清单</li><li><strong>九三是全卦的转折眼</strong>——「艰贞」强调持续用力，而非心血来潮</li><li><strong>六四的「不富」是最健康的富</strong>——富而不自知，才能自然带动周围</li><li><strong>六五的放低是「往下流动」</strong>——维持上下之气贯通，而非姿态谦逊</li><li><strong>上六的「贞吝」不是过失</strong>——泰极而否是天道必然，遗憾本身也是道的一部分</li></ol><blockquote><p>泰来了，它在。泰走了，它还在。 《易经》不是教人抓住泰，而是教人在泰与否之间，守住那个不随泰否而动摇的东西——那个贞，那个孚，那个中。</p></blockquote><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p><strong>「拔茅茹」的自我映射</strong></p><p>以《易经》为起点，自然带动了对庄子、道德经、六爻、奇门遁甲的探索。这种学习是「被带出来的」，而非刻意计划的，具有极强的生命力。</p><p><strong>泰卦的修行观</strong></p><p>功夫不在于雕刻行为，而在于「通气」。当内部阳气流动，外部自然通达，君子之德自然长成。</p><p><strong>「艰贞」的自我定位</strong></p><p>当下的处境更贴近九三——已开始拔茅茹式的学习探索，但重点不在于是否跨过九二的「包荒」气概，而在于九三「艰贞」的持续用力：不是心血来潮，而是日日重新守正，方能无咎。</p><p><strong>文言的密度</strong></p><p>「遐」字比「远」字多了偏远、难以企及的质感；「冯河」既有徒步涉险的莽勇，也有不假外力的自信；这些文言用字，值得细品。</p><p><strong>待推进</strong></p><p>后续可将「交流与通达」的内核映射至历史盛世或人物命运，作为写作素材；并结合已成稿的《多多益善与损之又损》（韩信与张良），进一步梳理「损益」与「泰否」两组卦理的互文关系。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：坤（第二卦）、否（第十二卦）——泰与否互为综卦，「天地交」与「天地不交」是同一结构的反面</li><li>泰否的连结：泰极而否，否极泰来。上六「城复于隍」正是泰转向否的自然节点，读否卦时可对照本卦九三「无平不陂，无往不复」</li></ul>',34))])}const _=l(d,[["render",p]]);export{q as __pageData,_ as default};
